def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def opp(i):
        return history[i][1]

    def me(i):
        return history[i][0]

    c_opp = 0
    c_me = 0
    for i in range(n):
        if opp(i) == 'C':
            c_opp += 1
        if me(i) == 'C':
            c_me += 1
    d_opp = n - c_opp
    d_me = n - c_me

    if d_opp == 0:
        if d_me == 0:
            if n >= 10:
                return 'D'
            return 'C'
        else:
            confirmed = False
            for i in range(n - 1):
                if history[i][0] == 'D' and history[i][1] == 'C' and history[i+1][0] == 'C' and history[i+1][1] == 'C':
                    confirmed = True
                    break
            if confirmed:
                return 'D'
            if history[-1][0] == 'D' and history[-1][1] == 'C':
                return 'C'
            return 'C'

    last_opp = opp(n - 1)
    last_me = me(n - 1)

    streak_d = 0
    i = n - 1
    while i >= 0 and opp(i) == 'D':
        streak_d += 1
        i -= 1
    streak_c = 0
    i = n - 1
    while i >= 0 and opp(i) == 'C':
        streak_c += 1
        i -= 1

    coop_rate = c_opp / n
    remaining = 100 - n

    mutual_d_streak = 0
    i = n - 1
    while i >= 0 and opp(i) == 'D' and me(i) == 'D':
        mutual_d_streak += 1
        i -= 1

    if mutual_d_streak >= 2 and coop_rate > 0.55:
        if mutual_d_streak == 2 and coop_rate > 0.6:
            return 'C'
        if n >= 2 and history[-1][0] == 'C' and history[-1][1] == 'D':
            if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'D':
                return 'C'
            if n >= 2 and history[-2][0] == 'C' and history[-2][1] == 'D':
                return 'D'

    if remaining <= 5:
        mirror_score = 0
        for i in range(1, n):
            if opp(i) == me(i-1):
                mirror_score += 1
        if mirror_score >= (n - 1) * 0.7:
            return 'C'
        if coop_rate > 0.6:
            return 'D'
        return 'C'

    if streak_d >= 2:
        return 'D'

    if streak_d == 1:
        if coop_rate > 0.7 and streak_c >= 3:
            return 'C'
        if n >= 4 and opp(n-3) == 'C' and opp(n-4) == 'C':
            return 'C'
        return 'D'

    if coop_rate >= 0.8:
        return 'C'

    if n >= 2:
        mirror_score = 0
        for i in range(1, n):
            if opp(i) == me(i-1):
                mirror_score += 1
        if mirror_score >= (n - 1) * 0.7:
            return me(n-1)

    if n >= 6:
        alt_score = 0
        for i in range(1, n):
            if opp(i) != opp(i-1):
                alt_score += 1
        if alt_score >= n - 2:
            if last_opp == 'C':
                return 'D'
            return 'C'

    if last_opp == 'C':
        return 'C'
    else:
        if coop_rate > 0.6 and streak_d <= 1:
            return 'C'
        if coop_rate > 0.5 and rng.random() < 0.3:
            return 'C'
        return 'D'
